package main
import ("encoding/base64";"encoding/hex";"fmt")
func main() {
  plain := "0d000721"
  l1 := rev(plain)
  xored := make([]byte, len(l1))
  for i := 0; i < len(l1); i++ { xored[i] = l1[i] ^ 0x5A }
  l3 := hex.EncodeToString(xored)
  l4 := base64.StdEncoding.EncodeToString([]byte(l3))
  fmt.Println(rev(l4))
}
func rev(s string) string {
  r := []rune(s)
  for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 { r[i], r[j] = r[j], r[i] }
  return string(r)
}
